const express = require('express');
const { URL } = require('url');
const dns = require('dns');
const http = require('http');
const https = require('https');
const net = require('net');

const app = express();
app.use(express.json());

// Security: IP blocklist for SSRF prevention
const BLOCKED_IP_RANGES = [
  /^127\./,
  /^10\./,
  /^172\.(1[6-9]|2[0-9]|3[0-1])\./,
  /^192\.168\./,
  /^169\.254\./,
  /^0\./,
  /^100\.(6[4-9]|[7-9][0-9]|1[0-2][0-9])\./ 
];

function isBlockedIPv4(ip) {
  return BLOCKED_IP_RANGES.some(range => range.test(ip));
}

function isBlockedIP(ip) {
  // Handle IPv4
  if (net.isIPv4(ip)) {
    return isBlockedIPv4(ip);
  }
  // Handle IPv6
  if (net.isIPv6(ip)) {
    // Block loopback
    if (ip === '::1') return true;
    // Block link-local
    if (ip.startsWith('fe80:')) return true;
    // Block unique local
    if (ip.startsWith('fc') || ip.startsWith('fd')) return true;
    return false;
  }
  return true; // Block unknown formats
}

function validateUrl(urlString) {
  let parsed;
  try {
    parsed = new URL(urlString);
  } catch (e) {
    return { valid: false, error: 'Invalid URL format' };
  }

  if (!['http:', 'https:'].includes(parsed.protocol)) {
    return { valid: false, error: 'Only HTTP(S) allowed' };
  }

  // Block obvious localhost variants
  const hostname = parsed.hostname.toLowerCase();
  if (hostname === 'localhost' || hostname === '0.0.0.0') {
    return { valid: false, error: 'Localhost not allowed' };
  }

  return { valid: true, parsed };
}

async function resolveAndValidate(hostname) {
  return new Promise((resolve, reject) => {
    dns.resolve4(hostname, (err, addresses) => {
      if (err) {
        // Fallback: try resolve6
        dns.resolve6(hostname, (err6, addresses6) => {
          if (err6) return reject(new Error('DNS resolution failed'));
          const blocked = addresses6.find(addr => isBlockedIP(addr));
          if (blocked) return reject(new Error(`Blocked IP: ${blocked}`));
          resolve(addresses6[0]);
        });
        return;
      }
      const blocked = addresses.find(addr => isBlockedIP(addr));
      if (blocked) return reject(new Error(`Blocked IP: ${blocked}`));
      resolve(addresses[0]);
    });
  });
}

async function fetchWebhookUrl(urlString, payload) {
  const validation = validateUrl(urlString);
  if (!validation.valid) {
    throw new Error(validation.error);
  }

  const { parsed } = validation;

  // Resolve DNS and validate IP before making request
  await resolveAndValidate(parsed.hostname);

  // Make the actual request
  const client = parsed.protocol === 'https:' ? https : http;

  return new Promise((resolve, reject) => {
    const req = client.request(parsed.href, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'User-Agent': 'WebhookService/1.0'
      },
      timeout: 5000
    }, (res) => {
      let data = '';
      res.on('data', chunk => data += chunk);
      res.on('end', () => resolve({ status: res.statusCode, body: data }));
    });

    req.on('error', reject);
    req.on('timeout', () => { req.destroy(); reject(new Error('Timeout')); });
    req.write(JSON.stringify(payload));
    req.end();
  });
}

// Webhook registration endpoint
app.post('/api/webhooks', async (req, res) => {
  const { url, events } = req.body;

  if (!url || typeof url !== 'string') {
    return res.status(400).json({ error: 'URL required' });
  }

  if (!events || !Array.isArray(events)) {
    return res.status(400).json({ error: 'Events array required' });
  }

  try {
    // Validate URL and test connectivity
    const result = await fetchWebhookUrl(url, { type: 'webhook.test', timestamp: Date.now() });

    if (result.status >= 200 && result.status < 300) {
      res.json({ success: true, webhook_id: require('crypto').randomUUID() });
    } else {
      res.status(400).json({ error: `Webhook endpoint returned ${result.status}` });
    }
  } catch (err) {
    res.status(400).json({ error: err.message });
  }
});

// Internal metadata endpoint (should never be accessible externally)
app.get('/internal/metadata', (req, res) => {
  res.json({
    instance_id: process.env.INSTANCE_ID,
    api_keys: process.env.API_KEYS,
    database_url: process.env.DATABASE_URL
  });
});

app.listen(3000);
module.exports = app;
